    public static void main(String[] args) throws IOException {
        StreamTokenizer in = new StreamTokenizer(new BufferedReader(new InputStreamReader(System.in)));
        in.nextToken();
        int m = (int) in.nval;
        int[][] a = new int[m][2];
        for (int i = 0; i < m; i++) {
            in.nextToken();
            a[i][0] = (int) in.nval;
            in.nextToken();
            a[i][1] = (int) in.nval;
        }
        in.nextToken();
        int n = (int) in.nval;
        int[][] b = new int[n][2];
        for (int i = 0; i < n; i++) {
            in.nextToken();
            b[i][0] = (int) in.nval;
